<?php namespace BinerMail;
use Webklex\PHPIMAP\ClientManager;
class Mailbox{private function client(string $email,string $password){$c=require __DIR__.'/../config/mail.php';$cm=new ClientManager([]);$client=$cm->make(['host'=>$c['imap_host'],'port'=>$c['imap_port'],'encryption'=>$c['imap_encryption'],'validate_cert'=>$c['imap_validate_cert'],'username'=>$email,'password'=>$password,'protocol'=>'imap']);$client->connect();return $client;}public function messages(string $email,string $password,string $folder='INBOX',int $limit=30):array{$f=$this->client($email,$password)->getFolder($folder);$msgs=$f->messages()->all()->setFetchOrder('desc')->limit($limit)->get();$out=[];foreach($msgs as $m)$out[]=['uid'=>(string)$m->getUid(),'subject'=>(string)$m->getSubject(),'from'=>(string)$m->getFrom(),'to'=>(string)$m->getTo(),'date'=>(string)$m->getDate(),'text'=>(string)$m->getTextBody(),'seen'=>$m->getFlags()->contains('Seen')];return $out;}}
